'use strict';
let DATA;
const state={view:'overview',search:'',coverage:'all',page:1,predictionId:null};
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(n,d=0)=>n==null||!Number.isFinite(+n)?'Not recorded':(+n).toLocaleString('en-US',{maximumFractionDigits:d});
const percent=v=>v==null?'Not recorded':fmt(v*100,1)+'%';
const seconds=v=>v!=null&&v>0&&v<.001?'<0.001':fmt(v,3);
const metric=(v,l)=>`<div class="metric"><strong>${fmt(v)}</strong><span>${l}</span></div>`;
const badge=(text,status='')=>`<span class="badge ${esc(status)}">${esc(text)}</span>`;
const heading=(k,h,p)=>`<p class="eyebrow">${esc(k)}</p><h1>${esc(h)}</h1><p class="lede">${esc(p)}</p>`;
const status=(label,text)=>`<div class="status-line"><strong>${esc(label)}</strong><span>${esc(text)}</span></div>`;
function bars(rows,max){const m=max??Math.max(1,...rows.map(r=>r.value??0));return rows.map(r=>`<div class="bar-row"><span class="bar-label">${esc(r.label)}</span><span class="bar-track"><span class="bar-fill" style="width:${Math.max(0,Math.min(100,(r.value??0)/m*100))}%"></span></span><span class="bar-value">${fmt(r.value)}</span></div>`).join('');}
function modelStatus(){return DATA.models?String(DATA.models.status||'Result artifact recorded'):'No completed benchmark artifact recorded';}
const armLabel=id=>({lexical_retrieval:'Lexical extractive retrieval',qwen_base_closed:'Base model · closed book',qwen_base_rag:'Base model · retrieval',qwen_lora_closed:'LoRA · closed book',qwen_lora_rag:'LoRA · retrieval',base_rag_positive_control:'Base retrieval · training-source check'})[id]||id;
const countRate=(v,n)=>v==null?'Not applicable':`${fmt(Math.round(v*n))}/${fmt(n)} (${percent(v)})`;
function acquisitionStatus(){const a=DATA.acquisition;if(!a)return 'A current acquisition summary is not yet recorded. The historical dataset remains available.';return a.displayMessage||a.summary||`${fmt(a.successful_new_operations)} successful new operations; ${fmt(a.new_raw_caption_documents)} new raw-caption documents. Desired network: ${a.network_desired||'not recorded'}; observed network-policy state: ${a.network_observation_state||'not recorded'}. Inspect the dated probe records for actual responses.`;}
function harvest(){return window.HarvestView.render(DATA.harvest,DATA.artifacts);}
function harvestEntry(){const h=DATA.harvest;if(!h?.run&&!h?.inventory)return '<p class="caption"><a href="#harvest">Open acquisition &amp; downloads</a> to inspect the next exported source inventory.</p>';const date=h.run?.updated_at||h.inventory?.updated_at||h.inventory?.generated_at||h.inventory?.source_captured_at;return `<div class="notice"><strong>Source acquisition and saved files</strong><a href="#harvest">Open acquisition &amp; downloads</a> for the dated inventory, per-route enumeration and actual request outcomes. ${date?'Snapshot recorded '+esc(date)+'.':''} Research and model results below preserve the earlier frozen study.</div>`;}
function overview(){
 const c=DATA.baseline.coverage,q=DATA.baseline.qa,accounts=DATA.baseline.channels.filter(x=>x.videoCount>0).length,hasHarvest=!!(DATA.harvest?.run||DATA.harvest?.inventory);
 return heading('Cross-channel evidence · exploratory continuation',hasHarvest?'Source inventory and retained research results':DATA.models?'A small model pilot within a larger channeling corpus':'A research record with source-linked evidence',hasHarvest?'Inspect channel routes, actual requests and verified saved files in the acquisition ledger. Earlier corpus analyses and local-model experiments remain available below.':DATA.models?'Five methods were executed locally on a small held-out digest sample. Read their reference-word overlap together with control outputs, source availability and collection limitations.':'Compare source material, executed experiments and access limits. New result rows appear only when an executed artifact exists.')+
 harvestEntry()+status('Current record',`Analysis: ${DATA.analysis?'result artifact available':'pending'}. Local benchmark: ${modelStatus()}.`)+
 `<div class="metrics">${DATA.models?metric(DATA.models.arms.length,'Executed comparison arms')+metric(DATA.models.split.testQuestions,'Held-out digest questions')+metric(DATA.models.split.controls,'Unsupported-evidence controls')+metric(DATA.models.training?.optimizerSteps,'CPU adapter optimizer updates'):metric(c.videoCount,'Retained upload IDs')+metric(accounts,'Publishing groups with uploads')+metric(DATA.baseline.captionPilot,'Frozen English-caption vectors')+metric(q?.qaCandidates,'Digest Q&A candidates, one practitioner context')}</div>
 <div class="two-columns"><section class="panel"><h3>Study scope and evidence layers</h3><div class="table-wrap"><table><thead><tr><th>Material</th><th>Available unit</th><th>What it supports</th></tr></thead><tbody><tr><td>Public upload metadata</td><td>${fmt(c.videoCount)} IDs; ${fmt(accounts)} groups with uploads</td><td>Publishing-account, title, duration and missingness comparisons</td></tr><tr><td>Caption derivatives</td><td>${fmt(DATA.baseline.captionPilot)} frozen English-caption vectors</td><td>Frozen numerical comparisons; source speech not reverified</td></tr><tr><td>Digest Q&A</td><td>${fmt(q?.qaCandidates)} paraphrase pairs</td><td>Retrieval and local-model pilot within Darryl Anka context</td></tr><tr><td>New multi-channel dialogue</td><td>Not established</td><td>Requires actual transcripts and source/speaker attribution</td></tr></tbody></table></div></section>
 <section class="panel"><h3>Execution states</h3><div class="table-wrap"><table><thead><tr><th>Workstream</th><th>Recorded state</th></tr></thead><tbody><tr><td>Retained evidence analysis</td><td>${badge(DATA.analysis?'Artifact available':'Pending',DATA.analysis?'':'pending')}</td></tr><tr><td>Local model benchmark</td><td>${badge(modelStatus(),DATA.models?'':'pending')}</td></tr><tr><td>Collection</td><td>${DATA.acquisition?badge('Observed access ledger available'):badge('Summary pending','pending')}</td></tr><tr><td>Human / audiovisual validation</td><td>${badge('Not performed','pending')}</td></tr></tbody></table></div><p class="caption">Artifact existence does not imply a successful model arm or a successful collection operation. Inspect the recorded arm and operation states.</p></section></div>
 ${analysisOverview()}
 <div class="notice"><strong>Model answers are experiment outputs</strong>Token overlap with an inherited digest is a proxy metric. It does not establish the accuracy of the digest, the truth of a channeled claim, validated answer agreement or general performance across practitioners.</div>
 <div class="section-heading"><h2>Continue from the source material</h2><p>The earlier evidence explorer preserves searchable account statistics and 949 source-linked candidate paraphrases.</p></div><p><a class="button" href="../expansion/">Open the evidence explorer</a> <a class="button secondary" href="#methods">Inspect methods &amp; artifacts</a></p>`;
}
function analysisOverview(){
 const a=DATA.analysis;if(!a)return `<section class="section panel"><h3>New analytical diagnostics</h3><p>The continuation analysis is being generated from frozen source artifacts. Pending hypotheses are not displayed as findings.</p></section>`;
 const coverage=a.coverage||{},alignment=a.questionAnswerAlignment||{};
 return `<section class="section"><div class="section-heading"><h2>Executed analytical diagnostics</h2><p>Question/answer lexical alignment, retrieval-graph sensitivity and representation nuisance controls are descriptive analyses of the retained sample.</p></div>${DATA.figures.length?`<div class="figure-grid">${DATA.figures.map(f=>`<figure><a href="${esc(f.path)}"><img src="${esc(f.path)}" alt="${esc(f.title)}" loading="lazy"></a><figcaption><strong>${esc(f.title)}</strong> ${esc(f.caption)}</figcaption></figure>`).join('')}</div>`:'<p class="caption">Figure generation is pending. The executed numeric result artifact is available in Methods.</p>'}${questionSupportSensitivity()}<details><summary>Read the analysis limitations</summary><ul>${(a.limitations||[]).map(l=>`<li>${esc(typeof l==='string'?l:JSON.stringify(l))}</li>`).join('')}</ul></details></section>`;
}
function questionSupportSensitivity(){
 const s=DATA.analysis?.questionAnswerAlignment?.commonSupportStandardization;if(!s)return '';
 return `<details id="question-support"><summary>Inspect question-similarity support and selection sensitivity</summary><p>Quarantine groups are constructed using question similarity and link density. Differences between their answer cosines are selected lexical diagnostics, not estimates of the effect of source reuse.</p><div class="table-wrap"><table><thead><tr><th>Question-cosine bin</th><th>Within-group pairs</th><th>Cross-group pairs</th><th>Mean answer cosine, within</th><th>Mean answer cosine, cross</th><th>Shared-support weight</th></tr></thead><tbody>${s.bins.map(b=>`<tr><td>${esc(b.label)}</td><td>${fmt(b.withinPairs)}</td><td>${fmt(b.crossPairs)}</td><td>${fmt(b.withinMeanAnswerCosine,3)}</td><td>${b.crossMeanAnswerCosine==null?'Unsupported':fmt(b.crossMeanAnswerCosine,3)}</td><td>${b.standardizationWeight==null?'Excluded':percent(b.standardizationWeight)}</td></tr>`).join('')}</tbody></table></div><p>The ${fmt(s.commonSupportBins)} shared-support bins retain ${fmt(s.includedNeighborPairs)} pairs (${fmt(s.withinIncludedPairs)} within, ${fmt(s.crossIncludedPairs)} cross); ${fmt(s.excludedNeighborPairs)} pairs are excluded. Identical pooled-bin weights produce within/cross mean answer cosines of ${fmt(s.standardizedWithinMean,3)} / ${fmt(s.standardizedCrossMean,3)}. Unsupported high-similarity bins remain unavailable, not zero.</p><p>Coarse bins leave within-bin wording, topic, length and source-selection differences. Pairs share source candidates. The original all-neighbor results are preserved; this is not validated answer agreement, exact matching, an independent-pair confidence interval or causal source-reuse evidence.</p></details>`;
}
function experiments(){
 const m=DATA.models;
 let html=heading('Local computation · recorded runs','Local model experiments','Inspect the model revision, source split, hardware, training receipt and observed outputs. Closed-book, retrieval-augmented and adapted arms are separate treatments, not interchangeable evidence.')+
 status('Benchmark status',modelStatus());
 if(!m)return html+`<div class="notice"><strong>No completed local-model benchmark artifact is available yet</strong>Downloading a model or preparing an adapter is not a completed inference or training experiment. Results will appear only after the executed run writes its receipt. GPU execution is not assumed.</div>${hardwareSummary(DATA.modelHardware,DATA.modelProtocol?.baseModel)}${DATA.modelRunStatus?status('Recorded run state',JSON.stringify(DATA.modelRunStatus)):'<p class="caption">No run-state receipt recorded.</p>'}<p class="caption">This is the state captured when the dashboard was built, not live process monitoring. Partial run counts are not final benchmark scores.</p><p><a href="#methods">Inspect available public artifacts</a>.</p>`;
 const hw=m.hardware||{},split=m.split||{},arms=m.arms||[];
 html+=status('Model and compute',`${m.model?.id||'Model not recorded'} · ${hw.device||'device not recorded'} · ${fmt(hw.cpuThreads??hw.torchThreads)} threads · CUDA ${hw.cudaAvailable===false?'unavailable':hw.cudaAvailable===true?'available':'not recorded'}`);
 if(DATA.annotationComparison)html+=`<p class="caption"><a href="#experiments" data-scroll="annotation-comparison">Inspect the three-condition annotation check</a> · <a href="#experiments" data-scroll="annotation-raw-cases">Compare source-bound raw annotations</a></p>`;
 html+=`<div class="metrics">${metric(split.trainExamples,'Recorded training examples')}${metric(split.testQuestions,'Held-out test questions')}${metric(split.controls,'Control prompts')}${metric(arms.length,'Recorded experimental arms')}</div>`;
 const provenance=`<div class="two-columns">${hardwareSummary(hw,m.model)}<section class="panel"><h3>Split and leakage boundary</h3><p>${esc(split.groupRule||'Inspect the recorded split artifact for grouping and exclusions.')}</p><p>Training and retrieval evidence must exclude held-out answer gists. Lexically similar questions or shared original sessions can still cross upload-level splits; these remain possible leakage pathways until independently resolved.</p><p class="caption">${fmt(split.testQuestions)} test questions form a small diagnostic pilot. A deterministic split is reproducible, not representative of all practitioners or independent original sessions.</p></section></div>`;
 html+=`<section class="section"><div class="section-heading"><h2>Arm comparison</h2><p>${fmt(split.testQuestions)} held-out questions and ${fmt(split.controls)} unsupported-evidence controls per arm. AI-reference reconstruction is a proxy metric.</p></div><div class="table-wrap"><table><thead><tr><th>Arm</th><th>State / n</th><th>Token overlap F1</th><th>Seconds / question</th><th>Supplied source-ID membership</th><th>Strict marker emission on controls</th></tr></thead><tbody>${arms.map(a=>`<tr><td>${esc(a.label||armLabel(a.id))}<small>${esc(a.kind||'')}</small></td><td>${esc(a.status||'Recorded result')}<small>${fmt(a.n)} questions + ${fmt(a.controlN??split.controls)} controls</small></td><td class="numeric">${a.meanTokenF1==null?'Not recorded':fmt(a.meanTokenF1,3)}</td><td class="numeric">${seconds(a.meanSeconds)}</td><td class="numeric">${countRate(a.validCitationRate,a.n)}</td><td class="numeric">${countRate(a.abstentionRateOnControls,a.controlN??split.controls)}</td></tr>`).join('')||'<tr><td colspan="6">No arm rows are present in this artifact.</td></tr>'}</tbody></table></div><p class="caption">The lexical extractive baseline has no 40-token generation cap; the cap applies to the four Qwen arms. Token F1 measures multiset alphanumeric-token overlap with inherited AI digest answer gists, not factual accuracy. Source-ID membership is syntactic, not entailment. The control metric detects only exact <code>INSUFFICIENT_EVIDENCE</code>; a plain-language refusal can score zero. Latency includes query retrieval, tokenization and generation, excluding one-time model loading/index fitting; shared CPU load, input lengths and the ${fmt(m.generation?.maxNewTokens)}-token output cap affect it.</p><div class="notice"><strong>Read overlap scores alongside the control outputs</strong>The LoRA closed-book arm emitted the strict marker on ${countRate(arms.find(a=>a.id==='qwen_lora_closed')?.abstentionRateOnControls,split.controls)} controls; the LoRA retrieval arm did so on ${countRate(arms.find(a=>a.id==='qwen_lora_rag')?.abstentionRateOnControls,split.controls)}. These are marker counts, not validated general refusal rates. Retrieval has only 48 training examples, excluding held-out source groups. This pilot does not establish general superiority of fine-tuning or retrieval.</div></section>`;
 html+=modelDiagnostics()+predictionInspector()+contentLabelExperiment()+labelConditionComparison()+currentFamilyExperiment();
 html+=`<details><summary>Inspect hardware, source split and training provenance</summary>${provenance}${trainingSummary(m.training)}</details>`;
 html+=`<details><summary>Training and evaluation limits</summary><ul>${(m.limitations||[]).map(l=>`<li>${esc(l)}</li>`).join('')}</ul></details><p class="caption"><a href="model-results.json" download>Download the exact model-result artifact</a>. Base-model weights and local caches remain outside this public build. The explicitly labeled small pilot-adapter download, if present in Methods, requires the pinned Qwen base and is not a validated domain model.</p>`;
 return html;
}
function trainingSummary(t){
 if(!t)return '<div class="notice"><strong>No adapter-training receipt recorded</strong>Benchmark arm labels alone do not prove that training completed.</div>';
 return `<section class="section panel"><h3>Adapter-training receipt</h3><div class="table-wrap"><table><thead><tr><th>Status / device</th><th>Examples / microsteps</th><th>Optimizer updates</th><th>Training seconds</th><th>Trainable parameters</th><th>LoRA rank</th></tr></thead><tbody><tr><td>${esc(t.status)} · ${esc(t.device)}</td><td>${fmt(t.examples)} / ${fmt(t.microsteps)}</td><td>${fmt(t.optimizerSteps)}</td><td>${fmt(t.trainingSeconds,2)}</td><td>${fmt(t.trainableParameters)}</td><td>${fmt(t.loraRank)}</td></tr></tbody></table></div><p class="caption">One epoch over inherited digest paraphrases. Completed optimization demonstrates that the adapter trained; it does not validate factual accuracy or general performance. No GPU timing comparison was executed.</p></section>`;
}
function predictionInspector(){
 const records=DATA.predictions?.records||[];if(!records.length)return '';
 const prompts=[...new Map(records.map(r=>[r.id,r])).values()];
 if(!prompts.some(r=>r.id===state.predictionId))state.predictionId=prompts[0].id;
 return `<section class="section"><div class="section-heading"><h2>Inspect the generated responses</h2><p>${fmt(records.length)} recorded outputs. Reference gists are inherited AI summaries, not verified ground truth.</p></div><form id="prediction-filter" class="controls"><label>Held-out question or control<select name="predictionId">${prompts.map(r=>`<option value="${esc(r.id)}"${r.id===state.predictionId?' selected':''}>${r.control?'Control: ':''}${esc(r.question)}</option>`).join('')}</select></label><button class="button" type="submit">Inspect responses</button></form><div id="prediction-results">${predictionResults()}</div></section>`;
}
function predictionResults(){
 const rows=(DATA.predictions?.records||[]).filter(r=>r.id===state.predictionId);if(!rows.length)return '';
 const first=rows[0];
 return `<h3>${esc(first.question)}</h3><p class="caption">${first.control?'Unsupported-evidence control prompt':'Held-out source question'} · ${first.referenceVideoId?`<a href="https://www.youtube.com/watch?v=${esc(first.referenceVideoId)}" target="_blank" rel="noopener">Source recording ↗</a>`:'No supporting source in supplied evidence'}</p><details><summary>Inspect the reference and evaluation scope</summary><p>${esc(first.referenceAnswerGist||'No answer reference for this unsupported-evidence control.')}</p><p>Reference type: ${esc(first.groundTruthType)}. This is model reconstruction of an existing digest, not a verified answer to the underlying claim.</p></details>${rows.map(r=>`<article class="response"><div class="section-heading"><h3>${esc(armLabel(r.arm))}</h3><p>Word-overlap F1 ${fmt(r.tokenF1ToHeldoutDigest,3)} · ${seconds(r.seconds)} s · ${fmt(r.generatedTokens)} generated tokens</p></div><div class="run-output">${esc(r.output)}</div><p class="caption">${r.abstained?'Exact marker present.':'No exact marker; inspect wording rather than assuming no refusal.'} ${r.arm==='lexical_retrieval'?'Extractive copy; no generation cap.':r.generatedTokens>=DATA.models.generation.maxNewTokens?'Reached the '+DATA.models.generation.maxNewTokens+'-token generation cap.':'Below generation cap.'} Prompt truncated: ${r.promptTruncated===true?'yes':r.promptTruncated===false?'no':'not applicable / recorded'}. Source labels: ${esc((r.citedLabels||[]).join(', ')||'none')}.</p>${r.retrievedEvidence?.length?`<details><summary>Inspect supplied retrieval evidence</summary>${r.retrievedEvidence.map(e=>`<p><a href="${esc(e.sourceUrl)}" target="_blank" rel="noopener">[${esc(e.label)}] ${esc(e.question)} ↗</a><br>${esc(e.answerGist)}<br><small>Retrieval cosine ${fmt(e.cosine,3)} · training candidate ${esc(e.candidateId)}</small></p>`).join('')}<p>Evidence is a training-set digest paraphrase. Retrieval similarity and a valid label do not establish support for an output.</p></details>`:''}</article>`).join('')}`;
}
function hardwareSummary(hw,model){
 if(!hw)return '<section class="panel"><h3>Hardware and model</h3><p>No hardware receipt is available.</p></section>';
 return `<section class="panel"><h3>Hardware and model</h3><div class="table-wrap"><table><tbody><tr><th scope="row">Model</th><td>${esc(model?.id||'Not recorded')}</td></tr><tr><th scope="row">Revision</th><td class="hash">${esc(model?.revision||'Not recorded')}</td></tr><tr><th scope="row">License</th><td>${esc(model?.license||'Not recorded')}</td></tr><tr><th scope="row">Execution device</th><td>${esc(hw.device||'Not recorded')}</td></tr><tr><th scope="row">CPU threads</th><td>${fmt(hw.cpuThreads??hw.torchThreads)}</td></tr><tr><th scope="row">CUDA available</th><td>${hw.cudaAvailable===true?'Yes':hw.cudaAvailable===false?'No':'Not recorded'}</td></tr></tbody></table></div><p class="caption">Hardware is recorded from the local run. No GPU comparison is inferred from CPU results.</p></section>`;
}
function modelDiagnostics(){
 const d=DATA.modelDiagnostics;if(!d)return '<p class="caption">Separate post-hoc output diagnostics are not yet included in this frozen snapshot. The original strict-marker metric above is preserved.</p>';
 return `<section class="section" id="model-diagnostics"><div class="section-heading"><h2>Output and source-availability diagnostics</h2><p>Post-hoc checks are separate from the original five-arm scores. Refusal wording is a pattern match, not human-validated semantic accuracy.</p></div><div class="table-wrap"><table><thead><tr><th>Arm</th><th>Strict marker on controls</th><th>Post-hoc refusal phrase on controls</th><th>F1 after removing labels / marker</th><th>Question outputs at token cap</th><th>Questions with any retrieved evidence</th></tr></thead><tbody>${(d.arms||[]).map(a=>`<tr><td>${esc(armLabel(a.arm))}</td><td>${fmt(a.strictMarkerCount)}/${fmt(a.controlN)}</td><td>${fmt(a.posthocRefusalPhraseCount)}/${fmt(a.controlN)}</td><td>${fmt(a.contentOnlyTokenF1,3)}</td><td>${a.arm==='lexical_retrieval'?'Not applicable':fmt(a.qaGenerationCapHits)+'/'+fmt(a.qaN)}</td><td>${a.arm.endsWith('_rag')||a.arm==='lexical_retrieval'?fmt(a.qaWithAnyRetrievedEvidence)+'/'+fmt(a.qaN):'Not applicable'}</td></tr>`).join('')}</tbody></table></div><p class="caption">The refusal-language pattern was defined after inspecting the outputs, so this is an exploratory diagnostic. It can distinguish a plain “Insufficient evidence.” response from exact underscore-marker compliance without proving that every refusal is appropriate. Five of eight held-out queries supplied retrieval evidence; three supplied none. Source-label membership is not citation entailment.</p>${(d.citationPositiveControls||[]).length?`<h3>Source-plumbing checks on training questions</h3><p class="caption">These ${fmt(d.citationPositiveControls.length)} checks use questions already present in the training corpus. They are not held-out test items and do not enter the eight-question benchmark means.</p>${d.citationPositiveControls.map(c=>`<details><summary>${esc(armLabel(c.arm))} · ${esc(c.question)}</summary><p>${c.sourceUrl?`<a href="${esc(c.sourceUrl)}" target="_blank" rel="noopener">Supplied source ↗</a>`:''} · Training candidate ${esc(c.candidateId)}</p><p>Supplied answer gist: ${esc(c.suppliedAnswerGist)}</p><div class="run-output">${esc(c.output)}</div><p>Supplied-label membership: ${c.validSourceLabelPresent===true?'present':c.validSourceLabelPresent===false?'absent':'not recorded'}. Entailment human validated: ${c.entailmentHumanValidated===true?'yes':'no'}. Held-out evaluation: ${c.heldoutEvaluation===true?'yes':'no'}.</p></details>`).join('')}`:''}<details><summary>Inspect post-hoc diagnostic definitions and limits</summary><p>Refusal pattern: <code>${esc(d.refusalPhrasePattern)}</code>.</p><ul>${(d.limitations||[]).map(l=>`<li>${esc(l)}</li>`).join('')}</ul></details></section>`;
}
function contentLabelExperiment(){
 const c=DATA.contentLabels;if(!c)return '';
 return `<section class="section" id="content-label-experiment"><div class="section-heading"><h2>${c.parsedRecords>0&&c.sourceSpanInvalidParsedCount===c.parsedRecords?'Qwen2.5 text-label probe failed source-span checks':'Qwen2.5 text-label probe diagnostics'}</h2><p>Local model labels are compared with a keyword rule. Agreement between two methods is not human-ground-truth accuracy.</p></div><div class="metrics">${metric(c.n,'Digest pairs selected')}${metric(c.parsedRecords,'Model outputs parsed')}${metric(c.parseFailures,'Model output parse failures')}${metric(c.sourceSpanExactAndShortCount,'Exact short source spans returned')}</div><div class="table-wrap"><table><thead><tr><th>Diagnostic</th><th>Recorded count</th><th>Interpretation</th></tr></thead><tbody><tr><td>Conditional-method concordance</td><td>${fmt(c.conditionalMethodAgreementCount)}/${fmt(c.conditionalMethodAgreementDenominator)} (${percent(c.conditionalMethodAgreementRate)})</td><td>Conditional on parsed records; model versus rule, not human accuracy</td></tr><tr><td>Primary-theme dictionary concordance</td><td>${fmt(c.primaryThemeDictionaryConcordanceCount)}/${fmt(c.parsedRecords)} parsed</td><td>Keyword categories and model categories can disagree; neither is a gold label</td></tr><tr><td>Mean model latency</td><td>${seconds(c.meanSeconds)} s</td><td>Per recorded annotation; not comparable to the capped answer-generation task</td></tr></tbody></table></div><div class="notice"><strong>Inspect the annotation failures</strong>These are model-output categories, not corpus theme prevalence. Parsed category counts: ${esc(JSON.stringify(c.themeCounts))}. Parsed conditional labels: ${esc(JSON.stringify(c.conditionalLabelCounts||{}))}. Exact short source spans: ${fmt(c.sourceSpanExactAndShortCount)}/${fmt(c.sourceSpanEvaluableRecords??c.parsedRecords)} parsed records; ${fmt(c.sourceSpanInvalidParsedCount)} parsed spans failed the combined exact-substring and at-most-eight-word constraint. Output parsing and concordance do not validate the labels.</div>${contentLabelExamples()}<p class="caption">Source depth is inherited AI digest question/answer gists. No raw speech, original audiovisual recording or human coding was used to validate these labels. Exact source-span copying checks traceability, not interpretation.</p><details><summary>Inspect annotation limits and raw model outputs</summary><ul>${(c.limitations||[]).map(l=>`<li>${esc(l)}</li>`).join('')}</ul><p><a href="content-label-results.json" download>Label metrics JSON</a> · <a href="content-label-predictions.json" download>Raw model annotation outputs</a></p></details></section>`;
}
function contentLabelExamples(){
 const rows=DATA.contentLabelPredictions?.records||[];if(!rows.length)return '';
 return `<details><summary>Inspect all ${fmt(rows.length)} source-bound model-label cases</summary>${rows.map(r=>`<details><summary>${esc(r.question)} · ${r.parsed?'JSON parsed':'parse failed'}</summary><p>Source depth: AI-generated digest paraphrase. <a href="${esc(r.sourceUrl)}" target="_blank" rel="noopener">Recording source ↗</a> · ${esc(r.sourcePointer)}</p><p>Answer gist: ${esc(r.answerGist)}</p><div class="run-output">${esc(r.rawModelOutput)}</div><p>Dictionary conditional label: ${esc(r.dictionaryConditional)}; model label: ${esc(r.parsed?.conditional||'unparsed')}. Dictionary theme indicators: ${esc((r.dictionaryThemeIndicators||[]).join(', ')||'none')}; model theme: ${esc(r.parsed?.theme||'unparsed')}.</p><p>Exact short evidence span: ${r.evidenceSpanExactAndShort===true?'yes':'no'}. Human reviewed: ${r.humanReviewed===true?'yes':'no'}. ${r.parseError?'Parse error: '+esc(r.parseError):''}</p></details>`).join('')}</details>`;
}
const annotationCounts=counts=>Object.entries(counts||{}).map(([label,n])=>label.replaceAll('_',' ')+' '+fmt(n)).join('; ')||'none recorded';
const annotationConditionLabel=id=>({qwen25_original:'Qwen2.5 · original order',qwen25_reversed:'Qwen2.5 · reversed order',qwen35_original:'Qwen3.5 · original order'})[id]||id;
function labelConditionComparison(){
 const c=DATA.annotationComparison,o=DATA.optionOrder,n=DATA.newFamilyLabels,l=DATA.lexiconSensitivity;
 if(!c||!o||!n)return '';
 return `<section class="section" id="annotation-comparison"><div class="section-heading"><h2>Same excerpts, three annotation conditions</h2><p>All conditions use the same 12 inherited digest pairs and a 96-token generation cap. Parsing and quote compliance can be checked; semantic label accuracy has no human reference.</p></div><div class="table-wrap"><table><thead><tr><th>Condition</th><th>Parsed / attempted</th><th>Parse failures</th><th>Exact answer substrings</th><th>Exact + ≤8 words</th><th>Exact but overlength</th><th>Nonexact spans</th><th>Conditional-rule concordance</th><th>Always-yes baseline</th></tr></thead><tbody>${c.conditions.map(r=>`<tr data-condition="${esc(r.id)}"><td>${esc(annotationConditionLabel(r.id))}<small>${fmt(r.maxNewTokens)}-token cap</small></td><td>${fmt(r.parsedRecords)}/${fmt(r.n)}</td><td>${fmt(r.parseFailures)}</td><td>${fmt(r.sourceSpanExactCount)}/${fmt(r.parsedRecords)}</td><td>${fmt(r.sourceSpanExactAndShortCount)}/${fmt(r.parsedRecords)}</td><td>${fmt(r.sourceSpanExactButOverLengthCount)}</td><td>${fmt(r.sourceSpanNonexactCount)}</td><td>${fmt(r.conditionalMethodAgreementCount)}/${fmt(r.conditionalParsedDenominator)} (${percent(r.conditionalMethodAgreementRate)})</td><td>${fmt(r.conditionalAlwaysYesBaselineAgreementCount)}/${fmt(r.conditionalParsedDenominator)} (${percent(r.conditionalAlwaysYesBaselineRate)})</td></tr>`).join('')}</tbody></table></div><p class="caption">Span and concordance denominators include parsed records only; all 12 attempts remain in the raw inspector below. Exact means a nonempty, case-sensitive contiguous substring of the supplied answer gist. The combined constraint also requires at most eight whitespace-separated words. Five Qwen3.5 spans are exact but overlength; these are length failures, not invented quotations.</p><div class="two-columns"><section class="panel"><h3>Prompt-order sensitivity</h3><p>${fmt(o.pairedThemeChangedCount)}/${fmt(o.pairedParsedRecords)} cases parsed in both Qwen2.5 conditions changed theme. Each condition parsed ${fmt(o.originalParsedRecords)}/${fmt(o.n)} attempts; the paired denominator excludes parse failures.</p><p>First-listed option selected: original ${fmt(o.originalFirstOptionCount)}/${fmt(o.originalParsedRecords)}, reversed ${fmt(o.reversedFirstOptionCount)}/${fmt(o.reversedParsedRecords)}. The reversed first option was “unclear”; these outputs do not support simple first-option copying.</p><p class="caption">Model-output theme counts: original ${esc(annotationCounts(o.originalThemeCounts))}; reversed ${esc(annotationCounts(o.reversedThemeCounts))}. These are not corpus theme prevalence.</p></section><section class="panel"><h3>Newer-family annotation check</h3><p>Qwen3.5 parsed ${fmt(n.parsedRecords)}/${fmt(n.n)} outputs and returned ${fmt(n.sourceSpanExactAndShortCount)}/${fmt(n.parsedRecords)} combined-compliant evidence spans. Mean generation latency: ${seconds(n.meanSeconds)} s/excerpt on CPU; ${fmt(n.generationCapHits)} cap hits.</p><p>All ${fmt(n.parsedRecords)} conditional labels were “yes”: ${fmt(n.conditionalMethodAgreementCount)}/${fmt(n.conditionalMethodAgreementDenominator)} rule concordance equals the always-yes baseline. The original Qwen2.5 condition also equals its always-yes baseline.</p><p class="caption">Theme outputs: ${esc(annotationCounts(n.themeCounts))}. Architectures, tokenizers, chat templates and required runtimes differ. The common token cap is not an identical word budget. No general model ranking, human accuracy, audiovisual analysis or Qwen3.5 training follows.</p></section></div>${annotationComparisonExamples()}${l?`<details id="lexicon-sensitivity"><summary>Inspect the post-hoc conditional-keyword sensitivity</summary><p>The broad dependency rule matches ${fmt(l.originalConditionalCount)}/${fmt(l.n)} answer gists; the narrower rule matches ${fmt(l.stricterConditionalCount)}/${fmt(l.n)}, changing ${fmt(l.changedCount)}. It excludes “dependence” and “dependency” forms. Both rules remain unvalidated lexical indicators; the original selection and benchmark labels are preserved.</p><p>Original: <code>${esc(l.originalRegex)}</code><br>Narrower: <code>${esc(l.stricterRegex)}</code></p>${l.changedRecords.map(r=>`<article class="response"><p><a href="${esc(r.sourceUrl)}" target="_blank" rel="noopener">${esc(r.id)} ↗</a> · ${esc(r.sourcePointer)}</p><p>${esc(r.answerGist)}</p><p class="caption">Original indicator: ${String(r.originalConditionalIndicator)}; narrower indicator: ${String(r.stricterConditionalIndicator)}. Source SHA-256: <span class="hash">${esc(r.sourceSha256)}</span></p></article>`).join('')}<p class="caption">The rule was narrowed after inspecting a false-positive candidate. “Provided” can still be nonconditional. This is not a corrected human reference.</p><a href="conditional-lexicon-sensitivity.json" download>Exact rules and changed cases JSON</a></details>`:''}<details><summary>Inspect the annotation comparison protocols and limits</summary><p><a href="annotation-comparison.json" download>All condition diagnostics</a> · <a href="option-order-protocol.json" download>Option-order protocol</a> · <a href="qwen35-content-label-protocol.json" download>Newer-family protocol</a></p><ul>${c.limitations.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></details></section>`;
}
function annotationComparisonExamples(){
 const originals=DATA.contentLabelPredictions?.records||[],reversed=new Map((DATA.optionOrderPredictions?.records||[]).map(r=>[r.id,r])),newer=new Map((DATA.newFamilyLabelPredictions?.records||[]).map(r=>[r.id,r]));
 return `<details id="annotation-raw-cases"><summary>Inspect all ${fmt(originals.length)} cases across the three conditions</summary>${originals.map(r=>`<details class="annotation-case" data-case-id="${esc(r.id)}"><summary>${esc(r.question)}</summary><p>Inherited AI digest paraphrase · <a href="${esc(r.sourceUrl)}" target="_blank" rel="noopener">Recording source ↗</a> · ${esc(r.id)} · ${esc(r.sourcePointer)}.</p><p>Supplied answer gist: ${esc(r.answerGist)}</p><p class="hash">Source SHA-256 ${esc(r.sourceSha256)}</p>${[
 {condition:'qwen25_original',record:r,parsed:r.parsed,raw:r.rawModelOutput},
 {condition:'qwen25_reversed',record:reversed.get(r.id),parsed:reversed.get(r.id)?.reversedParsed,raw:reversed.get(r.id)?.reversedRawOutput},
 {condition:'qwen35_original',record:newer.get(r.id),parsed:newer.get(r.id)?.parsed,raw:newer.get(r.id)?.rawModelOutput}
 ].map(x=>annotationCaseOutput(x,r.answerGist)).join('')}<p class="caption">Human reviewed: no. A valid exact span does not validate the model's theme, conditional label, the source speech or factual truth.</p></details>`).join('')}</details>`;
}
function annotationCaseOutput(x,gist){
 if(!x.record)return `<p>${esc(annotationConditionLabel(x.condition))}: no output artifact recorded.</p>`;
 const evidence=typeof x.parsed?.evidence==='string'?x.parsed.evidence:'',exact=!!evidence&&gist.includes(evidence),words=evidence.trim()?evidence.trim().split(/\s+/).length:0;
 return `<article class="response" data-condition="${esc(x.condition)}"><h3>${esc(annotationConditionLabel(x.condition))}</h3><div class="run-output">${esc(x.raw)}</div><p>JSON: ${x.parsed?'parsed':'failed'}. Theme: ${esc(x.parsed?.theme||'unparsed')}; conditional: ${esc(x.parsed?.conditional||'unparsed')}. Exact answer substring: ${x.parsed?(exact?'yes':'no'):'not evaluable'}; evidence words: ${x.parsed?fmt(words):'not evaluable'}; combined exact + ≤8 words: ${x.parsed?(exact&&words<=8?'pass':'fail'):'not evaluable'}.</p><p class="caption">${fmt(x.record.generatedTokens)} generated tokens · ${seconds(x.record.seconds)} s · ${x.record.generatedTokens>=96?'Reached 96-token cap.':'Below 96-token cap.'} ${x.record.parseError?'Parse error: '+esc(x.record.parseError):''}</p></article>`;
}
function currentFamilyExperiment(){
 const c=DATA.currentFamily;if(!c)return '<p class="caption">Current-family model smoke testing is separate and no completed receipt is included here.</p>';
 const name=typeof c.model==='string'?c.model:c.model?.id||c.modelId||'See the exact smoke-test receipt';
 return `<section class="section panel" id="current-family"><h3>Separate current-family text smoke test</h3><p>${esc(name)}</p>${status('Recorded state',String(c.status||'Not recorded'))}<div class="table-wrap"><table><tbody><tr><th scope="row">Actual task</th><td>${esc(c.taskActuallyRun??'Not recorded')}</td></tr><tr><th scope="row">Device</th><td>${esc(c.device||'Not recorded')}</td></tr><tr><th scope="row">Load time</th><td>${seconds(c.loadSeconds)} s</td></tr><tr><th scope="row">Generation time</th><td>${seconds(c.generationSeconds)} s</td></tr><tr><th scope="row">Generated tokens</th><td>${fmt(c.generatedTokens)}</td></tr></tbody></table></div>${c.status==='completed'&&c.rawOutput!=null?`<details><summary>Inspect the actual text output</summary><div class="run-output">${esc(c.rawOutput)}</div></details>`:''}<p class="caption">The prompt explicitly supplied the required field values. A single text-only instruction smoke task is not independent provenance inference, the five-arm question benchmark, an image task, a matched quality comparison or evidence of state-of-the-art performance. <a href="current-family-smoke.json" download>Exact run receipt</a>.</p></section>`;
}
function channelRecords(){
 const p=DATA.channelProgress;
 const rows=Array.isArray(p)?p:p?.records||p?.channels||[];
 const s=state.search.toLowerCase();
 return rows.filter(r=>(!s||JSON.stringify(r).toLowerCase().includes(s))&&(state.coverage==='all'||String(r.status||r.qaAvailability||'').includes(state.coverage)));
}
function collection(){return heading('Collection and identity · source access','Collection progress by channel candidate','Use operation-level evidence to distinguish available metadata, offered captions, blocked requests and planned work. Unrestricted desired access does not prove that a destination request succeeded.')+status('Observed access',acquisitionStatus())+collectionProbeSummary()+
 `<div class="notice"><strong>Only successful retrievals add source material</strong>A search plan, a connected account or a model download does not add a transcript. Raw captions and audiovisual material remain local-only where required; public builds contain source manifests, derived metrics and bounded paraphrases.</div><form id="collection-filters" class="controls"><label>Candidate or inherited entity label<input type="search" name="search" value="${esc(state.search)}" placeholder="Search the collection manifest"></label><button class="button" type="submit">Apply filter</button><button class="button secondary" type="button" data-action="export-collection">Export filtered coverage CSV</button></form><div id="collection-results">${collectionResults()}</div><details><summary>Collection and release boundaries</summary><p>Practitioner, uploader, claimed entity, upload and original session remain separate units. An inherited candidate identity is not revalidated by keyword matching. Publisher aliases merge only when a source bridge supports them.</p><p>Access-control errors are retained rather than evaded. Cookie or proxy-rotation workarounds are not treated as collection evidence. The acquisition workstream records actual software and request outcomes.</p></details>`;}
function collectionProbeSummary(){
 const a=DATA.acquisition;if(!a)return '';
 const when=a.checked_at?new Date(a.checked_at).toLocaleString('en-US',{timeZone:'America/New_York',month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})+' New York time':'Not recorded';
 return `<div class="two-columns"><section class="panel"><h3>General access probes</h3><div class="table-wrap"><table><tbody><tr><th scope="row">Public watch-page attempts</th><td>${fmt(a.new_public_watch_attempts)}</td></tr><tr><th scope="row">Author transcript-page attempts</th><td>${fmt(a.new_author_transcript_attempts)}</td></tr><tr><th scope="row">Successful new operations</th><td>${fmt(a.successful_new_operations)}</td></tr><tr><th scope="row">New raw-caption documents</th><td>${fmt(a.new_raw_caption_documents)}</td></tr></tbody></table></div><p class="caption">Recorded ${esc(when)}. Observed response classification: ${esc((a.observed_access||'Not recorded').replaceAll('_',' '))}. ${esc(a.note||'General access probes are distinct from candidate-level requests.')}</p></section><section class="panel"><h3>Collection queue sizes</h3><div class="table-wrap"><table><tbody><tr><th scope="row">Planned keyword queries</th><td>${fmt(a.planned_keyword_queries)}</td></tr><tr><th scope="row">Planned account routes</th><td>${fmt(a.planned_account_routes)}</td></tr><tr><th scope="row">Selected caption candidates</th><td>${fmt(a.selected_caption_candidates)}</td></tr><tr><th scope="row">Indexed actual transcript artifacts</th><td>${fmt(a.actual_transcript_artifacts_indexed)}</td></tr></tbody></table></div><p class="caption">The retained corpus index is metadata-backed. Historical caption availability and frozen numerical derivatives do not imply that raw caption files are retained in this new repository.</p></section></div>`;
}
function collectionResults(){
 const rows=channelRecords(),pages=Math.max(1,Math.ceil(rows.length/15));state.page=Math.min(state.page,pages);const page=rows.slice((state.page-1)*15,state.page*15);
 if(!rows.length)return `<p class="empty">${DATA.channelProgress?'No candidate matches this filter.':'No per-channel continuation progress manifest is recorded yet. The earlier evidence explorer retains the inherited 106-candidate roster.'}</p><p><a href="../expansion/#collection">Inspect the inherited collection frame</a></p>`;
 return `<p class="result-count">${fmt(rows.length)} matching inherited candidate records · no candidate-level failure is inferred from the general access probes</p><div class="table-wrap"><table><thead><tr><th>Inherited candidate</th><th>Planned queries / account routes</th><th>Candidate requests attempted</th><th>New caption tracks</th><th>Collection / attribution status</th></tr></thead><tbody>${page.map(r=>`<tr><td>${esc(r.name||r.practitioner_name||r.publisherName||r.practitioner_id||r.id)}<small>${esc((r.contextEntityLabels||r.entity_labels||[]).join(', '))}</small></td><td>${fmt(r.requested_plan_queries)} / ${fmt(r.requested_channel_routes)}</td><td>${fmt(r.keyword_queries_attempted)} search<br>${fmt(r.channel_crawls_attempted)} account<br>${fmt(r.caption_video_requests_attempted)} caption</td><td>${fmt(r.caption_tracks_retrieved)}</td><td>${esc((r.collection_status||r.status||'not_recorded').replaceAll('_',' '))}<small>Actual speaker: ${esc((r.actual_speaker_status||'not_recorded').replaceAll('_',' '))}</small><small>${esc((r.source_record_ids_inherited||[]).slice(0,2).join(', '))}</small></td></tr>`).join('')}</tbody></table></div><div class="pager"><span>Page ${state.page} of ${pages}</span><div><button class="button secondary" data-action="prev"${state.page===1?' disabled':''}>Previous</button><button class="button secondary" data-action="next"${state.page===pages?' disabled':''}>Next</button></div></div>`;
}
function methods(){
 const a=DATA.artifacts;
 return heading('Reproducibility · source inspection','Methods and reviewed artifacts','Each downloadable artifact is bound to its bytes and source classification. A frozen result can be reproduced without pretending that captions, identities or model answers have been independently validated.')+
 `<div class="two-columns"><section class="panel"><h3>What is public</h3><ul class="small-list"><li>Upload metadata and source-access manifests</li><li>Derived Q&A candidate database and bounded model outputs</li><li>Numerical analyses, chart inputs and scientific figure exports</li><li>Build scripts, working paper and source package</li><li>Model-agent review decisions and exact artifact hashes</li></ul></section><section class="panel"><h3>What remains outside this build</h3><ul class="small-list"><li>Full raw captions, audiovisual recordings and third-party message bodies</li><li>Downloaded base-model weights and local training caches; any small pilot adapter is labeled separately below</li><li>Credentials, private account data and local caches</li><li>Claims of human validation or newly verified ET origins</li></ul></section></div>
 <section class="section"><h2>Available downloads</h2><ul class="artifact-list">${a.map(f=>`<li><div class="artifact-heading"><a href="${esc(f.path)}" download>${esc(f.label)} ↓</a>${badge(f.kind)}</div><small>${fmt(f.bytes)} bytes · exact frozen artifact</small><div class="hash">SHA-256 ${esc(f.sha256)}</div></li>`).join('')}</ul></section>
 <details><summary>Sampling, units and prior evidence</summary><p>${esc(DATA.source.unit)}. The retained snapshot contains 925 upload IDs; 881 have measured duration. Thirty frozen English-caption vectors and 949 digest Q&A candidates are different text layers. All digest Q&A candidates come from one Darryl Anka practitioner context, across multiple publishing accounts.</p><p>Keyword-based extraction and TF-IDF retrieval measure lexical features. Embedding cosine is model representation similarity. Neither is a validated answer-agreement scale. New local-model evaluation uses inherited digest gists as proxy references and must report its small held-out sample and grouping rules.</p></details>
 <details><summary>What three model-agent panel rounds establish</summary><p>Each round reviews a changed artifact, records a finding and acceptance check, implements corrections, then tests the revision. This checks code, source lineage and claim support. It is not independent human peer review, human annotation or institutional ethics approval.</p></details>
 <details><summary>Stack and publication state</summary><p>This explorer extends the existing buildless HTML/CSS/JavaScript site. The shared Data runtime resource could not be read and its prebuilt authoring assets were unavailable. The public build uses local assets without remote script dependencies. A local verified build is distinct from a deployed Site.</p></details>
 <p class="caption">Frozen analytical source SHA-256: <code>${esc(DATA.source.baselineSha256)}</code>. Historical releases remain available through the <a href="../expansion/">evidence explorer</a> and <a href="../#/analysis">earlier atlas</a>.</p>`;
}
function render(){
 state.view=['overview','harvest','experiments','collection','methods'].includes(location.hash.slice(1))?location.hash.slice(1):'overview';
 document.querySelectorAll('.sections a').forEach(a=>a.setAttribute('aria-current',a.hash==='#'+state.view?'page':'false'));
 const nav=$('.sections'),selected=nav.querySelector('[aria-current=page]');if(selected)nav.scrollLeft=Math.max(0,selected.offsetLeft-nav.offsetLeft+selected.offsetWidth-nav.clientWidth+12);
 $('#app').innerHTML=({overview,harvest,experiments,collection,methods})[state.view]();
 document.title=({overview:'Research overview',harvest:'Acquisition & downloads',experiments:'Local model experiments',collection:'Collection & coverage',methods:'Methods & artifacts'})[state.view]+' — Channels ET';
}
function exportCollection(){
 const rows=channelRecords();if(!rows.length)return;
 const cols=[...new Set(rows.flatMap(r=>Object.keys(r)))];const quote=v=>{let s=v==null?'':typeof v==='object'?JSON.stringify(v):String(v);if(typeof v==='string'&&/^[=+\-@\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';};
 const content='\ufeff'+[cols.map(quote).join(','),...rows.map(r=>cols.map(c=>quote(r[c])).join(','))].join('\r\n');const u=URL.createObjectURL(new Blob([content],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=u;a.download='channels-et-filtered-coverage.csv';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);
}
document.addEventListener('submit',e=>{if(e.target.id==='harvest-filters'){e.preventDefault();$('#harvest-job-results').innerHTML=window.HarvestView.filter(e.target,DATA.harvest);}if(e.target.id==='harvest-route-filters'){e.preventDefault();$('#harvest-route-results').innerHTML=window.HarvestView.filterRoutes(e.target,DATA.harvest);}if(e.target.id==='collection-filters'){e.preventDefault();state.search=new FormData(e.target).get('search').trim();state.page=1;$('#collection-results').innerHTML=collectionResults();}if(e.target.id==='prediction-filter'){e.preventDefault();state.predictionId=new FormData(e.target).get('predictionId');$('#prediction-results').innerHTML=predictionResults();}});
document.addEventListener('click',e=>{const jump=e.target.closest('[data-scroll]');if(jump){e.preventDefault();const target=document.getElementById(jump.dataset.scroll);if(target){if(target.tagName==='DETAILS')target.open=true;target.tabIndex=-1;target.scrollIntoView({block:'start'});target.focus({preventScroll:true});}return;}const a=e.target.closest('[data-action]')?.dataset.action;if(a==='refresh-harvest')refreshHarvest();if(a==='export-harvest-jobs')window.HarvestView.exportJobs(DATA.harvest);if(a==='harvest-next'||a==='harvest-prev')$('#harvest-job-results').innerHTML=window.HarvestView.page(a==='harvest-next'?1:-1,DATA.harvest);if(a==='harvest-route-next'||a==='harvest-route-prev')$('#harvest-route-results').innerHTML=window.HarvestView.routePage(a==='harvest-route-next'?1:-1,DATA.harvest);if(a==='export-collection')exportCollection();if(a==='next'||a==='prev'){state.page+=a==='next'?1:-1;$('#collection-results').innerHTML=collectionResults();}});
async function refreshHarvest(){const button=$('[data-action=refresh-harvest]'),message=$('#harvest-refresh-status');if(button)button.disabled=true;if(message)message.textContent='Checking the published snapshot…';try{const response=await fetch('data.json?refresh='+Date.now(),{cache:'no-store'});if(!response.ok)throw Error('Published inventory request returned HTTP '+response.status);DATA=await response.json();render();const updated=$('#harvest-refresh-status');if(updated)updated.textContent='Published snapshot reloaded. Dates above show when the inventory was exported.';}catch(error){if(message)message.textContent='Snapshot refresh failed: '+error.message;if(button)button.disabled=false;}}
addEventListener('hashchange',()=>{render();$('#content').scrollIntoView({block:'start'});});
(async()=>{try{const r=await fetch('data.json');if(!r.ok)throw Error('Research snapshot unavailable');DATA=await r.json();render();}catch(e){$('#app').innerHTML=`<h1>Research data could not be loaded</h1><p class="lede">${esc(e.message)}</p><a class="button" href="../expansion/">Open the retained evidence explorer</a>`;}})();
